import {createChatOrchestrator} from './chatOrchestrator.js';
import type {OrchestratorHooks} from './chatOrchestrator.js';
import {ToolRegistry} from './tools/registry.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {AIProvider, MessageChunk, UsageMetadata} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';

// spec: specs/hal-engine-config-hooks/spec.md#1
const promptBuilder = new PromptBuilder({identity: 'Usage test.'});
const session = (): ChatSession => ({
  sessionId: 'usage-session',
  userId: 'usage-user',
  entries: [{role: 'user', content: 'Use the tools.', timestamp: '2026-01-01T00:00:00.000Z'}],
});

const providerForRounds = (rounds: MessageChunk[][]): AIProvider => {
  let round = 0;
  return {
    async *sendMessage(): AsyncGenerator<MessageChunk> {
      yield* rounds[round++] ?? [];
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
};

describe('afterModelResponse usage across tool rounds', () => {
  it('reports the sum of usage from every provider call', async () => {
    const toolCall: MessageChunk = {type: 'tool_use', toolCall: {id: 'lookup-1', name: 'lookup', input: {}}};
    const toolStop: MessageChunk = {type: 'stop', stopReason: 'tool_use'};
    const usageStop = (usage: UsageMetadata): MessageChunk => ({type: 'stop', stopReason: 'end_turn', usage});
    const registry = new ToolRegistry();
    registry.register({name: 'lookup', description: 'Looks up a value.', inputSchema: {type: 'object'}}, async () => 'found');
    let reported: UsageMetadata | undefined;
    const hooks: OrchestratorHooks = {
      afterModelResponse: async (_session, _text, usage) => {
        reported = usage;
      },
    };
    const orchestrator = createChatOrchestrator(
      providerForRounds([
        [toolCall, {...usageStop({inputTokens: 11, outputTokens: 2, totalTokens: 13}), stopReason: 'tool_use'}],
        [toolCall, {...usageStop({inputTokens: 23, outputTokens: 3, totalTokens: 26}), stopReason: 'tool_use'}],
        [{type: 'text', text: 'Done.'}, usageStop({inputTokens: 37, outputTokens: 5, totalTokens: 42})],
      ]),
      promptBuilder,
      registry,
      {hooks}
    );

    await orchestrator.processMessage(session());

    expect(reported).toEqual({inputTokens: 71, outputTokens: 10, totalTokens: 81});
  });
});
EOF
